using System;
using System.Configuration;
using System.Data;
using System.Data.SqlClient;

namespace BikeShop.Data
{
    // The ONE place the program talks to SQL Server.  Every method runs a
    // stored procedure.
    // Four things to know:  P makes a parameter.  Out makes an output
    // parameter.
    // GetTable runs a procedure that SELECTs rows.  Run runs a procedure that
    // changes data.
    public static class Db
    {
        #region ConnectionString
        // The connection string lives in App.config, so it can change without
        // touching the code.
        private static string ConnectionString
        {
            get
            {
                ConnectionStringSettingsCollection all =
                    ConfigurationManager.ConnectionStrings;
                return all["BikeShop"].ConnectionString;
            }
        }
        #endregion

        #region P
        // Makes a parameter to send to a procedure.  A C# null becomes a SQL
        // NULL.
        public static SqlParameter P(string name, object value)
        {
            if (value == null)
            {
                value = DBNull.Value;
            }
            return new SqlParameter(name, value);
        }
        #endregion

        #region Out
        // Makes an output parameter: the procedure fills it in, and you read
        // its .Value afterwards.
        public static SqlParameter Out(string name)
        {
            SqlParameter parameter = new SqlParameter(name, SqlDbType.Int);
            parameter.Direction = ParameterDirection.Output;
            return parameter;
        }
        #endregion

        #region GetTable
        // For procedures that SELECT rows.  Fills a DataTable you can put
        // straight into a grid or a combo box.
        public static DataTable GetTable(string procedureName,
            params SqlParameter[] parameters)
        {
            DataTable table = new DataTable();
            using (SqlConnection connection =
                new SqlConnection(ConnectionString))
            using (SqlCommand command = new SqlCommand(procedureName,
                connection))
            {
                command.CommandType = CommandType.StoredProcedure;
                command.Parameters.AddRange(parameters);
                using (SqlDataAdapter adapter = new SqlDataAdapter(command))
                {
                    adapter.Fill(table);
                }
            }
            return table;
        }
        #endregion

        #region Run
        // For procedures that change data.  Adds the @Message output parameter
        // itself and returns
        // whatever the procedure put in it.  "" means it worked.  Anything else
        // is a sentence to
        // show the user.  If SQL Server itself says no (a CHECK or a FOREIGN
        // KEY), that message
        // comes back the same way, so a screen never needs try and catch round
        // a database call.
        public static string Run(string procedureName,
            params SqlParameter[] parameters)
        {
            SqlParameter message = new SqlParameter("@Message",
                SqlDbType.VarChar, 200);
            message.Direction = ParameterDirection.Output;
            try
            {
                using (SqlConnection connection =
                    new SqlConnection(ConnectionString))
                using (SqlCommand command = new SqlCommand(procedureName,
                    connection))
                {
                    command.CommandType = CommandType.StoredProcedure;
                    command.Parameters.AddRange(parameters);
                    command.Parameters.Add(message);
                    connection.Open();
                    command.ExecuteNonQuery();
                }
            }
            catch (SqlException ex)
            {
                return ex.Message;
            }
            return message.Value.ToString();
        }
        #endregion
    }
}

namespace BikeShop.Models
{
    // One member of staff.  Plain properties only.
    public class StaffMember
    {
        public int StaffID { get; set; }
        public string FirstName { get; set; }
        public string LastName { get; set; }
        public string Role { get; set; }
        public string Username { get; set; }
        public string Password { get; set; }
    }
}

namespace BikeShop
{
    // Who is signed in.  Set once by frmLogin, read by any form that needs to
    // record who did something.
    public static class Session
    {
        public static int StaffID { get; private set; }
        public static string FullName { get; private set; }
        public static string Role { get; private set; }

        public static bool IsSignedIn
        {
            get { return StaffID > 0; }
        }

        public static bool IsManager
        {
            get { return Role == "Manager"; }
        }

        public static void SignIn(int staffID, string fullName, string role)
        {
            StaffID = staffID;
            FullName = fullName;
            Role = role;
        }

        public static void SignOut()
        {
            StaffID = 0;
            FullName = null;
            Role = null;
        }
    }
}

using System.Data;
using System.Data.SqlClient;
using BikeShop.Models;

namespace BikeShop.Data
{
    public static class StaffData
    {
        #region Login
        // Returns one row if the details match an active member of staff,
        // otherwise no rows.
        public static DataTable Login(string username, string password)
        {
            return Db.GetTable("usp_Staff_Login", Db.P("@Username", username),
                Db.P("@Password", password));
        }
        #endregion

        // The staff who are mechanics.
        public static DataTable GetMechanics()
        {
            return Db.GetTable("usp_Staff_GetMechanics");
        }

        // Every member of staff.
        public static DataTable GetAll()
        {
            return Db.GetTable("usp_Staff_GetAll");
        }

        // Saves a new member of staff.  Returns "" if it worked, or the
        // sentence to show the user.
        public static string Add(StaffMember staff)
        {
            SqlParameter newID = Db.Out("@NewStaffID");
            string message = Db.Run("usp_Staff_Add",
                Db.P("@FirstName", staff.FirstName),
                Db.P("@LastName", staff.LastName),
                Db.P("@Role", staff.Role),
                Db.P("@Username", staff.Username),
                Db.P("@Password", staff.Password),
                newID);
            if (message == "")
            {
                staff.StaffID = (int)newID.Value;
            }
            return message;
        }
    }
}

using System.Windows.Forms;

namespace BikeShop
{
    // Three kinds of message box, so every form says things the same way.
    public static class Msg
    {
        private const string Title = "Towpath Cycles";

        public static void Info(string text)
        {
            MessageBox.Show(text, Title, MessageBoxButtons.OK,
                MessageBoxIcon.Information);
        }

        public static void Problem(string text)
        {
            MessageBox.Show(text, Title, MessageBoxButtons.OK,
                MessageBoxIcon.Warning);
        }

        // Returns true when the user clicks Yes.
        public static bool Ask(string question)
        {
            return MessageBox.Show(question, Title, MessageBoxButtons.YesNo,
                MessageBoxIcon.Question) == DialogResult.Yes;
        }
    }
}

using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Drawing;
using System.Windows.Forms;
using BikeShop.Data;
using BikeShop.Models;

namespace BikeShop.Forms
{
    public partial class frmLogin : Form
    {
        public frmLogin()
        {
            InitializeComponent();
        }

        #region SignIn
        private void btnSignIn_Click(object sender, EventArgs e)
        {
            lblMessage.Text = "";
            string username = txtUsername.Text.Trim();
            string password = txtPassword.Text;

            if (username == "" || password == "")
            {
                lblMessage.Text = "Type your username and your password.";
                return;
            }

            // One row comes back when the details match an active member of
            // staff; no rows when they do not.
            // If SQL Server itself cannot be reached, say so instead of
            // crashing.
            DataTable match;
            try
            {
                match = StaffData.Login(username, password);
            }
            catch (SqlException)
            {
                lblMessage.Text =
                    "Could not reach the database. Is SQL Server running?";
                return;
            }
            if (match.Rows.Count == 0)
            {
                lblMessage.Text =
                    "Those details are not recognised. Check them and try " +
                    "again.";
                txtPassword.Clear();
                txtPassword.Focus();
                return;
            }

            DataRow staff = match.Rows[0];
            Session.SignIn((int)staff["StaffID"], (string)staff["FullName"],
                (string)staff["Role"]);

            frmMain main = new frmMain();
            // so we know when the main window closes
            main.FormClosed += Main_FormClosed;
            Hide();
            main.Show();
        }
        #endregion

        // The main window has closed.  After Sign out we come back here; after
        // the X the program ends.
        private void Main_FormClosed(object sender, FormClosedEventArgs e)
        {
            if (Session.IsSignedIn)
            {
                Close();
            }
            else
            {
                txtPassword.Clear();
                Show();
                txtUsername.Focus();
            }
        }
    }
}

